INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(43321985, 'Ancient Fairy Life Dragon', '上古精灵生命龙', 'エンシェント・フェアリー・ライフ・ドラゴン', 'Synchro Monster', 'Dragon', 'LIGHT', 8, 2500, 3300, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡同调召唤的场合才能发动。自己抽1张。场上有「精灵的世界」存在的场合，作为代替从卡组把1只光属性的兽族·植物族·天使族怪兽或者1张「永久圣阳光」加入手卡。 ②：自己的「古代妖精龙」以及有那个卡名记述的怪兽可以用表侧守备表示的状态作出攻击（伤害计算把守备力当作攻击力使用）。'),
(26304459, 'Ancient Flamvell Deity', '古代炎狱之神', 'エンシェント・ゴッド・フレムベル', 'Synchro Monster', 'Pyro', 'FIRE', 7, 2500, 200, '炎属性调整＋调整以外的炎族怪兽1只以上 这张卡同调召唤成功时，选择最多有对方手卡数量的对方墓地存在的卡从游戏中除外。这张卡的攻击力上升这个效果除外的卡数量×200的数值。'),
(87624166, 'Ancient Forest', '古之森', '古の森', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这张卡的发动时，场上有守备表示怪兽存在的场合，那些怪兽全部变成表侧攻击表示。这个时候，反转效果怪兽的效果不发动。此外，怪兽进行攻击的场合，进行攻击的怪兽在战斗阶段结束时破坏。'),
(300302022, 'Ancient Fusion', NULL, NULL, 'Skill Card', 'Dr. Vellian C', NULL, NULL, NULL, NULL, NULL),
(31557782, 'Ancient Gear', '古代的齿车', '古代の歯車', 'Effect Monster', 'Machine', 'EARTH', 2, 100, 800, '自己场上有「古代的齿车」表侧表示存在时，这张卡可以从手卡以攻击表示特殊召唤。'),
(4064925, 'Ancient Gear Advance', '古代机械齿轮进军', '古代の進軍', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能把卡盖放。 ①：作为这张卡的发动时的效果处理，从卡组把「古代的进军」以外的1张「古代的机械」魔法·陷阱卡加入手卡。 ②：1回合1次，把自己场上1只怪兽解放才能发动。自己抽1张，这个回合中，以下效果适用。 ●自己在「古代的机械巨人」或者有那个卡名记述的5星以上的怪兽召唤的场合需要的解放可以不用。'),
(10547580, 'Ancient Gear Ballista', '古代机械齿轮・弓弩手', '古代の機械弩士', 'Link Monster', 'Machine', 'EARTH', NULL, 1500, NULL, '机械族·地属性怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤的场合才能发动。从卡组把1只「古代的机械」怪兽或1张「齿车街」加入手卡。 ②：以自己场上1张魔法·陷阱卡和对方场上1只表侧表示怪兽为对象才能发动。那张自己的卡破坏，那只对方怪兽的攻击力·守备力直到回合结束时变成0。'),
(10509340, 'Ancient Gear Beast', '古代的机械兽', '古代の機械獣', 'Effect Monster', 'Machine', 'EARTH', 6, 2000, 2000, '这张卡不能特殊召唤。 ①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡战斗破坏的对方怪兽的效果无效化。'),
(60953949, 'Ancient Gear Box', '古代机械齿轮箱', '古代の機械箱', 'Effect Monster', 'Machine', 'EARTH', 4, 500, 2000, '这个卡名的效果1回合只能使用1次。 ①：这张卡用抽卡以外的方法从卡组·墓地加入手卡的场合才能发动。「古代的机械箱」以外的1只攻击力或守备力是500的机械族·地属性怪兽从卡组加入手卡。'),
(80045583, 'Ancient Gear Cannon', '古代的机械炮台', '古代の機械砲台', 'Effect Monster', 'Machine', 'EARTH', 2, 500, 500, '把这张卡作祭品。给与对方基本分500分的伤害，这个回合的战斗阶段中双方不能发动陷阱卡。'),
(92001300, 'Ancient Gear Castle', '古代的机械城', '古代の機械城', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：场上的「古代的机械」怪兽的攻击力上升300。 ②：只要这张卡在魔法与陷阱区域存在，每次怪兽通常召唤，给这张卡放置1个指示物。 ③：自己把「古代的机械」怪兽表侧表示上级召唤的场合，可以把有需要的解放数量以上的指示物放置的这张卡作为代替而解放来上级召唤。'),
(44052074, 'Ancient Gear Catapult', '古代机械齿轮弹射器', '古代の機械射出機', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上没有怪兽存在的场合，以自己场上1张表侧表示卡为对象才能发动。那张卡破坏，从卡组把1只「古代的机械」怪兽无视召唤条件特殊召唤。 ②：把墓地的这张卡除外，以自己场上1张表侧表示卡为对象才能发动。那张卡破坏，在自己场上把1只「古代的齿车衍生物」（机械族·地·1星·攻/守0）特殊召唤。'),
(27483935, 'Ancient Gear Commander', '古代机械齿轮司令', '古代の機械司令', 'Effect Monster', 'Machine', 'EARTH', 4, 500, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：从自己的手卡·卡组·场上（表侧表示）把1只「古代的机械巨人」送去墓地才能发动。进行1只「古代的机械」怪兽的召唤。 ②：自己把「古代的机械巨人」召唤·特殊召唤的场合才能发动。从自己的手卡·墓地把1只「古代的机械巨人」无视召唤条件特殊召唤。 ③：把墓地的这张卡除外才能发动。从手卡把1张「古代的机械」永续陷阱卡在自己场上表侧表示放置。'),
(64603182, 'Ancient Gear Dark Golem', '古代机械齿轮暗黑巨人', '古代の機械暗黒巨人', 'Effect Monster', 'Machine', 'EARTH', 8, 3000, 3000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡的卡名只要在场上·墓地存在当作「古代的机械巨人」使用。 ②：这张卡召唤·特殊召唤的场合才能发动。除「古代的机械暗黑巨人」外的「古代的机械」卡或「齿车街」合计最多2张从卡组加入手卡。那之后，选自己1张手卡丢弃。这个效果的发动后，直到回合结束时自己不能把卡盖放。 ③：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(75892194, 'Ancient Gear Dragon', '古代机械齿轮龙', '古代の機械竜', 'Effect Monster', 'Machine', 'EARTH', 5, 500, 2500, '这张卡不能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：自己场上的怪兽不存在的场合或者只有机械族·地属性怪兽的场合，这张卡可以不用解放作召唤。 ②：对方把魔法·陷阱卡的效果发动时，把自己的手卡·场上（表侧表示）1只机械族怪兽或者卡组1只「古代的机械巨人」送去墓地才能发动。那个效果无效。'),
(67829249, 'Ancient Gear Drill', '古代的采掘机', '古代の採掘機', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「古代的机械」怪兽存在的场合，丢弃1张手卡才能发动。从卡组选1张魔法卡在自己场上盖放。这个效果盖放的卡在这个回合不能发动。'),
(53541822, 'Ancient Gear Duel', '古代机械齿轮竞斗', '古代の機械競闘', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：自己的怪兽区域的「古代的机械巨人」以及有那个卡名记述的怪兽不受对方发动的怪兽的效果影响。 ②：对方场上有怪兽存在的场合才能发动。包含自己场上的「古代的机械巨人」的自己的场上·墓地的怪兽作为融合素材除外，把有「古代的机械巨人」的卡名记述的1只融合怪兽融合召唤。这个效果特殊召唤的怪兽在同1次的战斗阶段中可以作3次攻击。'),
(1953925, 'Ancient Gear Engineer', '古代的机械工兵', '古代の機械工兵', 'Effect Monster', 'Machine', 'EARTH', 5, 1500, 1500, '①：只要这张卡在怪兽区域存在，这张卡为对象的陷阱卡的效果无效化并破坏。 ②：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ③：这张卡攻击的伤害步骤结束时，以对方场上1张魔法·陷阱卡为对象发动。那张对方的魔法·陷阱卡破坏。'),
(4446672, 'Ancient Gear Explosive', '古代的机械爆弹', '古代の機械爆弾', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只名字带有「古代的机械」的怪兽作为对象才能发动。对象的怪兽破坏，给与对方基本分那只怪兽的原本攻击力一半数值的伤害。'),
(30435145, 'Ancient Gear Factory', '古代的机械工厂', '古代の機械工場', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择手卡1张名字带有「古代的机械」的怪兽卡。把墓地中合计为选择的卡2倍等级数量的名字带有「古代的机械」的卡从游戏中除外。选择的卡在这个回合召唤时不需要祭品。'),
(40830387, 'Ancient Gear Fist', '古代的机械掌', '古代の機械掌', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「古代的机械」的怪兽才能装备。和装备怪兽进行战斗的怪兽在那个伤害步骤结束时破坏。'),
(70147689, 'Ancient Gear Fortress', '古代机械齿轮要塞', '古代の機械要塞', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这个回合召唤·特殊召唤的自己场上的「古代的机械」怪兽不会被对方的效果破坏，对方不能把那些作为效果的对象。 ②：对方不能对应「古代的机械」卡的效果的发动把魔法·陷阱·怪兽的效果发动。 ③：魔法与陷阱区域的这张卡被破坏的场合才能发动。从自己的手卡·墓地把1只「古代的机械」怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是「古代的机械」怪兽不能特殊召唤。'),
(1278431, 'Ancient Gear Frame', '古代机械齿轮素体', '古代の機械素体', 'Effect Monster', 'Machine', 'EARTH', 4, 1600, 500, '这个卡名的①的效果1回合只能使用1次。 ①：丢弃1张手卡才能发动。把1只「古代的机械巨人」或者1张有那个卡名记述的魔法·陷阱卡从卡组加入手卡。 ②：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ③：表侧表示的这张卡因对方的效果从场上离开的场合才能发动。从手卡把「古代的机械巨人」「古代的机械巨人-究极重击」合计最多3只无视召唤条件特殊召唤。'),
(64061284, 'Ancient Gear Fusion', '古代机械齿轮结合', '古代の機械融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只「古代的机械」融合怪兽融合召唤。把自己场上的「古代的机械巨人」或「古代的机械巨人-究极重击」作为融合素材的场合，自己卡组的怪兽也能作为融合素材。'),
(18486927, 'Ancient Gear Gadget', '古代机械齿轮小工具', '古代の歯車機械', 'Effect Monster', 'Machine', 'EARTH', 4, 500, 2000, '①：这张卡召唤·特殊召唤成功的场合，宣言卡的种类（怪兽·魔法·陷阱）才能发动。这个回合，自己怪兽攻击的场合，对方直到伤害步骤结束时宣言的种类的卡不能发动。 ②：1回合1次，宣言1个「零件」怪兽的卡名才能发动。直到结束阶段，这张卡当作和宣言的卡同名卡使用。'),
(86321248, 'Ancient Gear Gadjiltron Chimera', '古代的机械合成兽', '古代の機械合成獣', 'Effect Monster', 'Machine', 'EARTH', 6, 2300, 1300, '①：得到为这张卡的召唤而解放的怪兽的以下效果。 ●绿色零件：这张卡的攻击力上升300。 ●红色零件：这张卡直接攻击给与对方战斗伤害的场合发动。给与对方500伤害。 ●黄色零件：这张卡战斗破坏对方怪兽的场合发动。给与对方700伤害。'),
(50933533, 'Ancient Gear Gadjiltron Dragon', '古代机械齿轮巨龙', '古代の機械巨竜', 'Effect Monster', 'Machine', 'EARTH', 8, 3000, 2000, '①：得到为这张卡的召唤而解放的怪兽的以下效果。 ●绿色零件：这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ●红色零件：这张卡给与对方战斗伤害的场合发动。给与对方400伤害。 ●黄色零件：这张卡战斗破坏对方怪兽的场合发动。给与对方600伤害。 ②：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(83104731, 'Ancient Gear Golem', '古代机械齿轮巨人', '古代の機械巨人', 'Effect Monster', 'Machine', 'EARTH', 8, 3000, 3000, '这张卡不能特殊召唤。 ①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(95735217, 'Ancient Gear Golem - Ultimate Pound', '古代机械齿轮巨人－究极重拳', '古代の機械巨人－アルティメット・パウンド', 'Effect Monster', 'Machine', 'EARTH', 8, 3000, 3000, '这张卡不能特殊召唤。 ①：这张卡向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。 ②：1回合最多2次，这张卡的攻击破坏怪兽时，从手卡丢弃1只机械族怪兽才能发动。这张卡可以继续攻击。 ③：场上的这张卡被战斗·效果破坏的场合才能发动。从卡组把1张「融合」加入手卡，从自己墓地把1只其他的「古代的机械」怪兽加入手卡。'),
(87182127, 'Ancient Gear Howitzer', '古代机械齿轮・魔神', '古代の機械魔神', 'Fusion Monster', 'Machine', 'EARTH', 8, 1000, 1800, '「古代的机械」怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：场上的这张卡不受其他卡的效果影响。 ②：自己主要阶段才能发动。给与对方1000伤害。 ③：这张卡被战斗破坏送去墓地的场合才能发动。从卡组把1只「古代的机械」怪兽无视召唤条件特殊召唤。'),
(42878636, 'Ancient Gear Hunting Hound', '古代机械齿轮猎犬', '古代の機械猟犬', 'Effect Monster', 'Machine', 'EARTH', 3, 1000, 1000, '①：这张卡召唤的场合发动。给与对方600伤害。 ②：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ③：1回合1次，自己主要阶段才能发动。自己的手卡·场上的怪兽作为融合素材，把1只「古代的机械」融合怪兽融合召唤。'),
(81269231, 'Ancient Gear Hydra', '古代机械齿轮合成龙', '古代の機械合成竜', 'Effect Monster', 'Machine', 'EARTH', 7, 2700, 1700, '①：和把「古代的机械」怪兽解放作上级召唤的这张卡的战斗没让对方怪兽被破坏的伤害步骤结束时才能发动。那只对方怪兽除外。 ②：把「零件」怪兽解放作上级召唤的这张卡可以向对方怪兽全部各作1次攻击。 ③：自己的「古代的机械」怪兽攻击的场合，对方直到伤害步骤结束时怪兽的效果·魔法·陷阱卡不能发动。'),
(39303359, 'Ancient Gear Knight', '古代的机械骑士', '古代の機械騎士', 'Gemini Monster', 'Machine', 'EARTH', 4, 1800, 500, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(37663536, 'Ancient Gear Megaton Golem', '古代机械齿轮・超巨人', '古代の機械超巨人', 'Fusion Monster', 'Machine', 'EARTH', 9, 3300, 3300, '「古代的机械」怪兽×3 ①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：从「古代的机械巨人」「古代的机械巨人-究极重击」之中以合计2只以上为素材作融合召唤的这张卡在同1次的战斗阶段中可以作出最多有那个数量的攻击。 ③：融合召唤的表侧表示的这张卡因对方的效果从场上离开的场合才能发动。从额外卡组把1只「古代的机械究极巨人」无视召唤条件特殊召唤。'),
(44874522, 'Ancient Gear Reactor Dragon', '古代机械齿轮・热核反应机龙', '古代の機械熱核竜', 'Effect Monster', 'Machine', 'EARTH', 9, 3000, 3000, '①：把「古代的机械」怪兽解放作上级召唤的这张卡向守备表示怪兽攻击的场合，给与攻击力超过那个守备力的数值的战斗伤害。 ②：把「零件」怪兽解放作上级召唤的这张卡在同1次的战斗阶段中可以作2次攻击。 ③：这张卡攻击的场合，对方直到伤害步骤结束时怪兽的效果·魔法·陷阱卡不能发动。 ④：这张卡攻击的伤害步骤结束时才能发动。选场上1张魔法·陷阱卡破坏。'),
(47482043, 'Ancient Gear Reborn', '古代机械齿轮苏生', '古代の機械蘇生', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「古代的机械苏生」在自己场上只能有1张表侧表示存在。 ②：1回合1次，自己场上没有怪兽存在的场合，以自己墓地1只「古代的机械」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽的攻击力上升200。'),
(56094445, 'Ancient Gear Soldier', '古代的机械士兵', '古代の機械兵士', 'Effect Monster', 'Machine', 'EARTH', 4, 1300, 1300, '①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。'),
(32762201, 'Ancient Gear Statue', '古代机械齿轮像', '古代の機械像', 'Effect Monster', 'Machine', 'EARTH', 2, 500, 800, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：对方场上的怪兽数量比自己场上的怪兽多的场合，这张卡可以从手卡特殊召唤。 ②：把这张卡解放才能发动。除「古代的机械像」外的1只「古代的机械巨人」或者有那个卡名记述的怪兽从手卡·卡组无视召唤条件特殊召唤。'),
(37457534, 'Ancient Gear Tank', '古代的机械战车', '古代の機械戦車', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「古代的机械」的怪兽才能装备。装备怪兽的攻击力上升600。这张卡被破坏送去墓地时，给与对方基本分600分伤害。'),
(91098230, 'Ancient Gear Tanker', '古代机械齿轮战车兵', '古代の機械戦車兵', 'Effect Monster', 'Machine', 'EARTH', 4, 1300, 1300, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从手卡把「古代的机械战车兵」以外的1只「古代的机械」怪兽无视召唤条件特殊召唤。对方场上有怪兽存在的场合，也能作为代替从自己墓地选。 ②：以自己场上1张表侧表示卡为对象才能发动。那张卡破坏。这个回合中自己场上的「古代的机械巨人」以及有那个卡名记述的怪兽的攻击力上升600。'),
(44052075, 'Ancient Gear Token', '古代机械齿轮弹射器', '古代の機械射出機', 'Token', 'Machine', NULL, NULL, NULL, NULL, NULL),
(59811955, 'Ancient Gear Workshop', '古代的整备场', '古代の整備場', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「古代的机械」怪兽为对象才能发动。那只怪兽加入手卡。'),
(17663375, 'Ancient Gear Wyvern', '古代机械齿轮飞龙', '古代の機械飛竜', 'Effect Monster', 'Machine', 'EARTH', 4, 1700, 1200, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。从卡组把「古代的机械飞龙」以外的1张「古代的机械」卡加入手卡。这个效果的发动后，直到回合结束时自己不能把卡盖放。 ②：这张卡攻击的场合，对方直到伤害步骤结束时怪兽的效果不能发动。'),
(81492226, 'Ancient Jar', '太古之壶', '太古の壺', 'Normal Monster', 'Rock', 'EARTH', 1, 400, 200, '非常脆弱的太古之壶。里面好像藏着什么东西。'),
(54912977, 'Ancient Lamp', '魔法神灯', 'マジック・ランプ', 'Effect Monster', 'Spellcaster', 'WIND', 3, 900, 1400, '①：自己主要阶段才能发动。这张卡在场上表侧表示存在的场合，从手卡把1只「灯之魔精」特殊召唤。 ②：里侧守备表示的这张卡被对方怪兽攻击的伤害计算前，以攻击怪兽以外的1只对方怪兽为对象才能发动。攻击对象转移为那只对方怪兽进行伤害计算。'),
(11830996, 'Ancient Leaf', '古之叶', 'エンシェント・リーフ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己基本分是9000以上的场合，支付2000基本分才能发动。自己从卡组抽2张。'),
(43230671, 'Ancient Lizard Warrior', '古代的蜥蜴战士', '古代のトカゲ戦士', 'Normal Monster', 'Reptile', 'EARTH', 4, 1400, 1100, '远古的保持着昔日姿态的蜥蜴战士，意外的强悍。'),
(14015067, 'Ancient One of the Deep Forest', '大森林的长老', '深き森の長老', 'Normal Monster', 'Beast', 'EARTH', 6, 1800, 1900, '很久以前住在森林里的白羊，真身是森林长老。'),
(4179255, 'Ancient Pixie Dragon', '妖精龙 上古', '妖精竜 エンシェント', 'Synchro Monster', 'Dragon', 'DARK', 7, 2100, 3000, '调整＋调整以外的怪兽1只以上 自己回合有场地魔法卡发动的场合，从卡组抽1张卡。「妖精龙 古代妖」的这个效果1回合只能使用1次。此外，1回合1次，场地魔法卡表侧表示存在的场合，可以选择场上表侧攻击表示存在的1只怪兽破坏。'),
(300302056, 'Ancient Ruler Rises', NULL, NULL, 'Skill Card', 'Abidos the Th', NULL, NULL, NULL, NULL, NULL),
(10667321, 'Ancient Rules', '古之规则', '古のルール', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只5星以上的通常怪兽特殊召唤。'),
(25958491, 'Ancient Sacred Wyvern', '上古圣翼龙', 'エンシェント・ホーリー・ワイバーン', 'Synchro Monster', 'Fairy', 'LIGHT', 7, 2100, 2000, '光属性调整＋调整以外的怪兽1只以上 自己基本分比对方高的场合，这张卡的攻击力上升那个数值。自己基本分比对方低的场合，这张卡的攻击力下降那个数值。这张卡被战斗破坏送去墓地时，可以支付1000基本分把这张卡在自己场上特殊召唤。'),
(36821538, 'Ancient Sorcerer', '古代魔导士', '古代魔導士', 'Normal Monster', 'Spellcaster', 'DARK', 4, 1000, 1300, '拿着许多手杖。各自分别使用多样的攻击。'),
(17092736, 'Ancient Telescope', '古代的望远镜', '古代の遠眼鏡', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '查看对方卡组最上面的最多5张卡，然后放回原处。'),
(49587396, 'Ancient Tool', '钢铁之心', 'アイアン・ハート', 'Normal Monster', 'Machine', 'DARK', 5, 1700, 1400, '在古代文明遗迹里发现的机器。破坏是它的唯一目的。'),
(86421986, 'Ancient Tree of Enlightenment', '悟道的老树', '悟りの老樹', 'Normal Monster', 'Plant', 'EARTH', 3, 600, 1500, '运用所有知识、能够守备各种攻击的老树。'),
(33545259, 'Ancient Warriors - Ambitious Cao De', '战华之孟－曹德', '戦華の孟－曹徳', 'Effect Monster', 'Beast-Warrior', 'FIRE', 8, 3000, 2500, '这个卡名的①③的效果1回合各能使用1次。 ①：对方场上的卡被战斗·效果破坏的场合，把这张卡以外的自己的手卡·场上1张卡送去墓地才能发动。这张卡从手卡特殊召唤。 ②：只要自己场上有其他的「战华」怪兽存在，这张卡不会成为对方的效果的对象，不会被对方的效果破坏。 ③：这张卡战斗破坏对方怪兽送去墓地时才能发动。那只怪兽在自己场上守备表示特殊召唤。'),
(6438003, 'Ancient Warriors - Deceptive Jia Wen', '战华之诡－贾文', '戦華の詭－賈文', 'Effect Monster', 'Beast-Warrior', 'FIRE', 4, 1100, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张永续魔法·永续陷阱卡为对象才能发动。那张卡送去墓地，选场上2只表侧表示怪兽，那些攻击力直到回合结束时变成一半。 ②：对方场上的卡被战斗·效果破坏的场合，以「战华之诡-贾文」以外的自己墓地1张「战华」卡为对象才能发动。那张卡加入手卡。'),
(13923256, 'Ancient Warriors - Eccentric Lu Jing', '战华之妙－鲁敬', '戦華の妙－魯敬', 'Effect Monster', 'Beast-Warrior', 'WATER', 4, 700, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张永续魔法·永续陷阱卡为对象才能发动。那张卡送去墓地，从自己墓地选和那张卡卡名不同的1张「战华」魔法·陷阱卡加入手卡。 ②：这张卡以外的自己的「战华」怪兽的效果发动的场合，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。'),
(60033398, 'Ancient Warriors - Fearsome Zhang Yuan', '战华之来－张远', '戦華の来－張遠', 'Effect Monster', 'Beast-Warrior', 'FIRE', 6, 2300, 2000, '这个卡名的①③的效果1回合各能使用1次。 ①：自己的「战华」怪兽和对方的表侧表示怪兽进行战斗的伤害步骤开始时才能发动。这张卡从手卡特殊召唤，那只对方怪兽的攻击力下降1000。 ②：这张卡以外的自己的「战华」怪兽不会被战斗破坏。 ③：对方场上的卡被战斗·效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(77539547, 'Ancient Warriors - Graceful Zhou Gong', '战华之美－周公', '戦華の美－周公', 'Effect Monster', 'Beast-Warrior', 'WATER', 4, 1600, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1张永续魔法·永续陷阱卡为对象才能发动。那张卡送去墓地，从卡组把1张「战华」魔法·陷阱卡加入手卡。 ②：这张卡以外的自己的「战华」怪兽的效果发动的场合，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。'),
(32422602, 'Ancient Warriors - Ingenious Zhuge Kong', '战华之智－诸葛孔', '戦華の智－諸葛孔', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1000, 2000, '这个卡名的①②③的效果1回合各能使用1次。 ①：这张卡用「战华」卡的效果从卡组加入手卡的场合才能发动。这张卡特殊召唤。 ②：魔法·陷阱卡发动时，把自己场上1张表侧表示的「战华」永续魔法·永续陷阱卡送去墓地才能发动。那个发动无效。 ③：自己场上有「战华之德-刘玄」存在，怪兽的效果发动时，把自己场上1张表侧表示的「战华」永续魔法·永续陷阱卡送去墓地才能发动。那个发动无效。'),
(76416959, 'Ancient Warriors - Loyal Guan Yun', '战华之义－关云', '戦華の義－関雲', 'Effect Monster', 'Beast-Warrior', 'WIND', 7, 2500, 1800, '这个卡名的③的效果1回合只能使用1次。 ①：只有对方场上才有怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：只要这张卡在怪兽区域存在，自己场上的其他的「战华」怪兽不会成为对方的效果的对象。 ③：对方场上的怪兽数量比自己场上的怪兽多的场合，以对方场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(40140448, 'Ancient Warriors - Masterful Sun Mou', '战华之仲－孙谋', '戦華の仲－孫謀', 'Effect Monster', 'Beast-Warrior', 'WATER', 4, 1800, 1500, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有其他的「战华」怪兽存在，对方不能选择这张卡作为攻击对象。 ②：从自己的手卡·场上把1张卡送去墓地才能发动。从卡组把「战华之仲-孙谋」以外的1只「战华」怪兽加入手卡。 ③：这张卡以外的自己的「战华」怪兽的效果发动的场合，以对方场上1只怪兽为对象才能发动。那只怪兽回到持有者手卡。'),
(82791472, 'Ancient Warriors - Rebellious Lu Feng', '战华之叛－吕奉', '戦華の叛－呂奉', 'Effect Monster', 'Beast-Warrior', 'DARK', 8, 2800, 2200, '这张卡不能通常召唤。「战华之叛-吕奉」1回合1次在场上的「战华」怪兽之内攻击力最高的怪兽在自己场上存在的场合才能特殊召唤。 ①：双方的主要阶段才能发动1次。对方场上1只攻击力最高的怪兽破坏。这个效果发动的回合，自己不能把「战华」怪兽以外的怪兽效果发动。 ②：结束阶段，场上的攻击力最高的怪兽在对方场上存在的场合发动。这个控制权移给对方。'),
(79582540, 'Ancient Warriors - Savage Don Ying', '战华之暴－董颖', '戦華の暴－董穎', 'Effect Monster', 'Beast-Warrior', 'DARK', 6, 2200, 1800, '这个卡名的①③的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1只7星以上的「战华」怪兽或者1张「战华」永续魔法·永续陷阱卡加入手卡。 ②：只要自己场上有7星以上的「战华」怪兽存在，对方若不支付400基本分，则不能把卡的效果发动。 ③：怪兽被送去对方墓地的场合，以对方墓地1张卡为对象才能发动。那张卡除外，自己从卡组抽1张。'),
(2801664, 'Ancient Warriors - Valiant Zhang De', '战华之雄－张德', '戦華の雄－張徳', 'Effect Monster', 'Beast-Warrior', 'WIND', 7, 2700, 900, '这个卡名的①③的效果1回合各能使用1次。 ①：自己场上有「战华」怪兽2只以上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡的攻击力在自己回合内上升对方场上的怪兽数量×300。 ③：对方场上的怪兽数量比自己场上的怪兽多的场合才能发动。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(40428851, 'Ancient Warriors - Virtuous Liu Xuan', '战华之德－刘玄', '戦華の徳－劉玄', 'Effect Monster', 'Beast-Warrior', 'WIND', 4, 1400, 1200, '这个卡名的②③的效果1回合各能使用1次。 ①：只要自己场上有其他的「战华」怪兽存在，对方不能选择这张卡作为攻击对象。 ②：对方场上的怪兽数量比自己场上的怪兽多的场合，从自己的手卡·场上把1张卡送去墓地才能发动。从卡组把「战华之德-刘玄」以外的1只「战华」怪兽特殊召唤。 ③：这张卡以外的自己的「战华」怪兽进行战斗的攻击宣言时才能发动。自己从卡组抽1张。'),
(65711558, 'Ancient Warriors Oath - Double Dragon Lords', '战华盟将－双龙', '戦華盟将－双龍', 'Link Monster', 'Beast-Warrior', 'WIND', NULL, 1100, NULL, '包含风属性「战华」怪兽的兽战士族怪兽2只 这个卡名的①③的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「战华」卡加入手卡。 ②：自己场上的「战华」怪兽的攻击力·守备力上升500。 ③：从自己的手卡·场上把1张卡送去墓地，以对方场上1张表侧表示的卡为对象才能发动。那张卡回到持有者手卡。这个效果在对方回合也能发动。'),
(33609093, 'Ancient Warriors Saga - Borrowing of Arrows', '战华史略－十万之箭', '戦華史略－十万之矢', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以对方场上1只表侧表示怪兽和自己场上1只「战华」怪兽为对象才能发动。直到回合结束时，那只对方怪兽的攻击力变成一半，那只自己怪兽的攻击力上升那个数值。 ②：自己场上的「战华」怪兽的属性是2种类以上，这张卡被送去墓地的场合才能发动。从手卡·卡组把「战华史略-十万之矢」以外的1张「战华」永续魔法·永续陷阱卡在自己场上表侧表示放置。'),
(82255872, 'Ancient Warriors Saga - Chivalrous Path', '战华史略－大丈夫之义', '戦華史略－大丈夫之義', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①③的效果1回合各能使用1次。 ①：对方对怪兽的特殊召唤成功的场合才能发动。在自己场上把1只「战华的龙兵衍生物」（兽战士族·风·1星·攻/守500）特殊召唤。 ②：自己·对方的「战华」怪兽被战斗破坏的场合，可以作为代替把这张卡送去墓地。 ③：场上的「战华」怪兽为对象的魔法·陷阱·怪兽的效果发动时，把墓地的这张卡除外才能发动。那个发动无效。'),
(45115956, 'Ancient Warriors Saga - Deception and Betrayal', '战华史略－矫诏之叛', '戦華史略－矯詔之叛', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段才能发动。从手卡把1只「战华」怪兽特殊召唤，自己受到那只怪兽的等级×100伤害。 ②：把魔法与陷阱区域的表侧表示的这张卡送去墓地，以场上1只「战华」怪兽为对象才能发动。那只怪兽的属性变更为任意属性。以对方场上的怪兽为对象发动的场合，可以再得到那只怪兽的控制权。'),
(4810585, 'Ancient Warriors Saga - Defense of Changban', '战华史略－长坂之雄', '戦華史略－長坂之雄', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合只能有1次使用其中任意1个。 ①：自己的「战华」怪兽进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：对方战斗阶段开始时，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。这个回合，对方不能选择「战华」怪兽作为攻击对象。 ③：对方怪兽的攻击宣言时，把墓地的这张卡除外才能发动。从卡组把1只「战华」怪兽特殊召唤。'),
(62528292, 'Ancient Warriors Saga - East-by-South Winds', '战华史略－东南之风', '戦華史略－東南之風', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第2次的自己准备阶段送去墓地。 ①：1回合1次，自己主要阶段才能发动。进行1次投掷硬币。表的场合，这张卡送去墓地。 ②：这张卡从魔法与陷阱区域送去墓地的场合才能发动。这个回合对方不能对应自己的「战华」卡的效果的发动把效果发动，自己场上的全部「战华」效果怪兽直到回合结束时得到以下效果。 ●这张卡的攻击宣言时才能发动。选对方场上1张卡破坏。'),
(58116537, 'Ancient Warriors Saga - Sun-Liu Alliance', '战华史略－孙刘同盟', '戦華史略－孫劉同盟', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上的「战华」怪兽的属性是2种类以上的场合，宣言1个属性才能发动。持有宣言的属性的对方场上的全部怪兽直到回合结束时不能把效果发动。 ②：对方对怪兽的特殊召唤成功的场合或者自己把「战华」怪兽的效果发动的场合才能发动。自己场上的全部「战华」怪兽的攻击力直到回合结束时上升自己场上的「战华」怪兽数量×300。'),
(11711438, 'Ancient Warriors Saga - Three Visits', '战华史略－三顾礼迎', '戦華史略－三顧礼迎', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动后，第2次的自己准备阶段送去墓地。这个卡名的①②的效果1回合各能使用1次。 ①：自己主要阶段，自己对「战华」怪兽的召唤·特殊召唤成功的场合，以那1只怪兽为对象才能发动。和那只怪兽卡名不同的1只「战华」怪兽从卡组加入手卡。 ②：这张卡从魔法与陷阱区域送去墓地的场合才能发动。从手卡把1只「战华」怪兽特殊召唤。'),
(47594939, 'And the Band Played On', '召唤限制－不协和领域', '召喚制限－ディスコードセクター', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方玩家不能把持有和自身场上的怪兽相同等级的怪兽特殊召唤。此外，双方玩家不能把持有和自身场上的怪兽相同阶级的怪兽特殊召唤。'),
(15013468, 'Andro Sphinx', '斯芬克斯·安德鲁', 'アンドロ・スフィンクス', 'Effect Monster', 'Beast', 'LIGHT', 10, 3000, 2500, '场上有「光之金字塔」存在的场合，可以支付500基本分把这张卡从手卡特殊召唤。这张卡在召唤·特殊召唤的回合不能攻击。这张卡不能作从墓地的特殊召唤。这张卡战斗破坏守备表示怪兽的场合，给与对方基本分破坏的怪兽的攻击力一半数值的伤害。'),
(53266486, 'Anesthrokket Dragon', '麻醉枪弹龙', 'アネスヴァレット・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 1, NULL, 2200, '这个卡名的①②的效果1回合各能使用1次。 ①：场上的这张卡为对象的连接怪兽的效果发动时才能发动。这张卡破坏。那之后，选场上1只表侧表示怪兽。那只怪兽不能攻击，效果无效化。 ②：场上的这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。从卡组把「麻醉弹丸龙」以外的1只「弹丸」怪兽特殊召唤。'),
(82243738, 'Angel O1', '天使欧１', 'エンジェルO１', 'Effect Monster', 'Fairy', 'LIGHT', 1, 200, 300, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：这张卡可以把手卡1只7星以上的怪兽给对方观看，从手卡特殊召唤。 ②：只要特殊召唤的这张卡在怪兽区域存在，自己在通常召唤外加上只有1次，自己主要阶段可以把1只7星以上的怪兽表侧攻击表示上级召唤。'),
(56784842, 'Angel O7', '天使O7', 'エンジェルO７', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2500, 1500, '这张卡的祭品召唤成功时，这张卡得到以下效果。 ●只要这张卡在场上表侧表示存在，效果怪兽不能把效果发动。'),
(91706817, 'Angel of Blue Tears', '青泪的天使', '青い涙の天使', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：以场上1只表侧表示怪兽为对象才能发动。从那只怪兽的控制者来看的对方受到自身手卡数量×200伤害。那之后，作为对象的怪兽的效果直到回合结束时无效。 ②：自己或对方受到效果伤害的场合，把墓地的这张卡除外才能发动。从手卡·卡组把1张通常陷阱卡在自己场上盖放。从手卡盖放的场合，那张卡在盖放的回合也能发动。'),
(42216237, 'Angel of Zera', '杰拉的天使', 'ゼラの天使', 'Synchro Monster', 'Fairy', 'LIGHT', 8, 2800, 2300, '调整＋调整以外的怪兽1只以上 「杰拉的天使」的②的效果1回合只能使用1次。 ①：这张卡的攻击力上升除外的对方的卡数量×100。 ②：这张卡被除外的场合，下个回合的准备阶段发动。除外的这张卡特殊召唤。'),
(44822037, 'Angel Statue - Azurune', '碑像天使－亚兹卢恩', '碑像の天使－アズルーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（天使族·光·4星·攻/守1800）在怪兽区域特殊召唤（也当作陷阱卡使用）。 ②：这张卡是已用这张卡的效果特殊召唤的场合，1回合1次，对方把怪兽特殊召唤之际，把从魔法与陷阱区域特殊召唤的自己的怪兽区域1张永续陷阱卡送去墓地才能发动。那次特殊召唤无效，那些怪兽破坏。 ③：这张卡被战斗破坏时才能发动。把让这张卡破坏的怪兽破坏。'),
(87979586, 'Angel Trumpeter', '天使曼陀号手', 'エンジェル・トランペッター', 'Normal Tuner Monster', 'Plant', 'EARTH', 4, 1900, 1600, '如天使般的美丽之花。它不断地释放出一种雾来迷惑侵入者，不允许其进入圣兽们居住的森林最深处。'),
(36320744, 'Angelica, Princess of Noble Arms', '巡历圣剑的王姬 安洁莉卡', '聖剣を巡る王姫アンジェリカ', 'Synchro Monster', 'Warrior', 'FIRE', 5, 1200, 2400, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合才能发动。从卡组把1张有「焰圣骑士帝-查理」的卡名记述的卡或者「象牙角笛」加入手卡。 ②：场上的这张卡成为攻击·效果的对象时才能发动。从卡组把1只战士族·炎属性怪兽送去墓地，这张卡直到结束阶段除外。那之后，可以从卡组·额外卡组把1只「罗兰」怪兽特殊召唤。'),
(40678060, 'Angelica''s Angelic Ring', '天子的指环', '天子の指輪', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '有装备卡装备的自己场上的怪兽才能装备。 ①：「天子的指轮」在自己场上只能有1张表侧表示存在。 ②：对方发动的魔法卡的效果1回合只有1次无效化。 ③：1回合1次，这张卡装备中的场合才能发动。自己回复500基本分。那之后，这张卡破坏，以下效果适用。 ●只要这张卡装备过的怪兽在怪兽区域表侧表示存在，对方不能把那只怪兽作为效果的对象。'),
(3048768, 'Angello Vaalmonica', '天使之声・华耳琴璃', '天使の聲', 'Pendulum Effect Monster', 'Fairy', 'DARK', 4, 1200, 2100, '这个卡名的①②的怪兽效果1回合各能使用1次。 ①：这张卡在手卡存在的场合，从手卡丢弃1张其他卡才能发动。从卡组选1只「恶魔之声」，这张卡和那张卡在自己的灵摆区域放置。 ②：这张卡召唤·特殊召唤的回合的自己主要阶段，从自己墓地把1张「异响鸣」通常魔法·通常陷阱卡除外才能发动。那张魔法·陷阱卡发动时的回复基本分的选项的效果适用。'),
(65612386, 'Angmarl the Fiendish Monarch', '魔帝安格马', '魔帝アングマール', 'Effect Monster', 'Fiend', 'DARK', 6, 2400, 1000, '①：这张卡上级召唤成功时，把自己墓地1张魔法卡除外才能发动。把1张除外的那张魔法卡的同名卡从卡组加入手卡。'),
(73979030, 'Angraecum Umbrella', '相爱之彗星兰伞', '相愛のアンブレカム', 'Tuner Monster', 'Spellcaster', 'WATER', 3, 500, 1500, '①：这张卡召唤成功时，丢弃1张手卡，以自己墓地1只4星以下的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不是同调怪兽不能从额外卡组特殊召唤。'),
(28306253, 'Angry Burger', '饥怒汉堡', 'アングリーバーガー', 'Ritual Effect Monster', 'Warrior', 'DARK', 6, 2800, 1850, '「食谱」卡降临 这个卡名在规则上当作「饥饿的汉堡」使用。这个卡名的①③的效果1回合各能使用1次。 ①：把手卡的这张卡给对方观看才能发动。从卡组把1只「新式魔厨」怪兽加入手卡，这张卡回到卡组。 ②：可以攻击的对方怪兽必须向这张卡作出攻击。 ③：自己·对方回合可以发动。自己·对方场上1只攻击表示怪兽解放，从手卡·卡组把1只攻击力2000的「饥饿的汉堡」特殊召唤。'),
(98022050, 'Animadorned Archosaur', '珠玉兽－祖龙', '珠玉獣－アルゴザウルス', 'Effect Monster', 'Dinosaur', 'LIGHT', 1, NULL, NULL, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合才能发动。「珠玉兽-运算主龙」以外的自己的手卡·场上（表侧表示）1只恐龙族怪兽破坏。那之后，原本等级和那只破坏的怪兽相同的1只爬虫类族·海龙族·鸟兽族怪兽或者1张「进化药」魔法卡从卡组加入手卡。'),
(595626, 'Ankuriboh', '安卡栗子球', 'アンクリボー', 'Effect Monster', 'Fiend', 'DARK', 1, 300, 200, '这个卡名的①②的效果1回合各能使用1次。 ①：对方怪兽的攻击宣言时把这张卡从手卡丢弃，以这张卡以外的自己或者对方的墓地1只怪兽为对象才能发动。那只怪兽在自己场上特殊召唤。这个效果特殊召唤的怪兽在结束阶段送去墓地。 ②：这张卡被战斗·效果破坏送去墓地的场合才能发动。这个回合的结束阶段，从自己的卡组·墓地选1张「死者苏生」加入手卡。'),
(29603180, 'Annihilator Archfiend', '灾害恶魔', 'ディザスター・デーモン', 'Effect Monster', 'Fiend', 'DARK', 9, 2000, 3000, '这个卡名的效果1回合只能使用1次。 ①：以自己以及对方场上的卡各1张为对象才能发动。那些卡破坏。这个效果把表侧表示的恶魔族怪兽破坏的场合，这张卡的攻击力直到回合结束时上升那些怪兽的原本攻击力合计数值的一半。'),
(47484352, 'Anotherverse Dragon', '异宇宙龙', 'アナザー・バース・ドラゴン', 'Normal Monster', 'Dragon', 'LIGHT', 8, 2500, 2000, '统治诸多次元的龙。仅限时任霸者可见。'),
(86893702, 'Anotherverse Gluttonia', '异宇宙暴食魔', NULL, 'Normal Monster', 'Fiend', 'DARK', 8, 2500, 2000, '吞噬不同次元的巨大邪恶魔物。它塑造了只有强者栖身的多个领域。'),
(63028558, 'Anotherverse Solaria', '异宇宙暮阳神', NULL, 'Normal Monster', 'Pyro', 'FIRE', 8, 2500, 2000, '庇护着暮阳的异世界之星神。不断地追求新的力量，其冰之炎在次元上留下灼热的痕迹。'),
(10949074, 'Anotherverse Stratios', '异宇宙战煌', 'アナザー・バース・ストラディオス', 'Normal Monster', 'Warrior', 'EARTH', 8, 2500, 2000, '跨越几亿战火的异界军神。汝若想获此威光，就尽管来取吧。'),
(48365709, 'Ansatsu', '暗杀者', 'アサシン', 'Normal Monster', 'Warrior', 'EARTH', 5, 1700, 1200, '能在黑暗中悄然无声地靠近敌人，精通暗杀的战士。'),
(34236961, 'Ante', '打赌胜负', 'アンティ勝負', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '双方各自选择1张手卡并展示，相互确认等级。选择等级较高卡的一方将选出的卡放回手卡，选择等级较低卡的一方受到1000点伤害，将选出的卡送去墓地。选择怪兽卡以外的卡时，等级强制计为0。双方选择的卡等级相同时，各自将选出的卡放回手卡。'),
(13250922, 'Anteatereatingant', '食大食蚁兽蚁', 'オオアリクイクイアリ', 'Effect Monster', 'Insect', 'EARTH', 5, 2000, 500, '这张卡不能通常召唤。把自己场上2张魔法·陷阱卡送去墓地的场合才能特殊召唤。这张卡可以作为攻击的代替而把对方场上1张魔法·陷阱卡破坏。'),
(89904598, 'Anthrosaurus', '恐龙人', '恐竜人', 'Normal Monster', 'Dinosaur', 'EARTH', 3, 1000, 850, '人形的恐龙。虽然智慧很高，但攻击力却不怎么强劲。'),
(42364257, 'Anti Raigeki', '避雷针', '避雷針', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方使用了「雷击」的时候，破坏对方全部怪兽代替自己的怪兽。发动后这张卡破坏。'),
(65064143, 'Anti-Aircraft Flower', '对空放花', '対空放花', 'Effect Monster', 'Plant', 'EARTH', 3, NULL, 1600, '每祭掉自己场上1只昆虫族怪兽，给与对方基本分800分的伤害。'),
(72150572, 'Anti-Fusion Device', '融合体驱除装置', '融合体駆除装置', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '场上表侧表示存在的1只融合怪兽破坏。'),
(97120394, 'Anti-Magic Arrows', '封魔之矢', '封魔の矢', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '不能对应这张卡的发动让魔法·陷阱·怪兽的效果发动。 ①：自己或者对方的战斗阶段开始时才能发动。这张卡的发动后，直到回合结束时双方不能把魔法·陷阱卡的效果发动。'),
(20138923, 'Anti-Magic Prism', '反魔镜', '反魔鏡', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方把速攻魔法卡发动时才能发动。选择场上存在的1张卡破坏。'),
(53112492, 'Anti-Spell', '对抗魔术', '対抗魔術', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把自己场上存在的2个魔力指示物取除发动。魔法卡的发动无效并破坏。'),
(58921041, 'Anti-Spell Fragrance', '魔封之芳香', '魔封じの芳香', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，双方魔法卡若不盖放则不能发动，直到从盖放的玩家来看的下次的自己回合到来不能发动。'),
(43583400, 'Antialian', '抗锯齿星人', 'アンチエイリアン', 'Effect Monster', 'Cyberse', 'EARTH', 4, 1900, 600, '①：1回合1次，这张卡和怪兽进行过战斗的自己·对方的战斗阶段才能发动。从手卡把1只电子界族怪兽召唤。 ②：表侧表示的这张卡因对方的效果从场上离开的场合发动。自己从卡组抽1张。'),
(31539614, 'Antidote Nurse', '苗丁格尔', 'ワクチンゲール', 'XYZ Monster', 'Machine', 'LIGHT', 3, 1800, 1200, '3星怪兽×2只以上 ①：自己·对方回合，把这张卡1个超量素材取除，以攻击力或守备力和原本数值不同的场上1只怪兽为对象才能发动。那只怪兽的攻击力·守备力变成原本数值。以自己场上的怪兽为对象发动的场合，再让那只怪兽在这个回合不会被战斗·效果破坏。 ②：1回合1次，自己场上有其他怪兽特殊召唤的场合，若这张卡的超量素材是3个以上则能发动。那些怪兽的攻击力上升900。'),
(58844135, 'Antihuman Intelligence ME-PSY-YA', '人攻智能ME－PSY－YA', '人攻智能ME－PSY－YA', 'Pendulum Effect Monster', 'Cyberse', 'LIGHT', 8, 2500, 3000, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。选这张卡以外的手卡1只灵摆怪兽或者自己的灵摆区域1张卡表侧表示加入持有者的额外卡组，这张卡特殊召唤。 ②：这张卡已在怪兽区域存在的状态，其他怪兽召唤·特殊召唤的场合发动。那些怪兽在这个回合的结束阶段送去墓地。'),
(60411677, 'Anubis the Last Judge', '裁决之阿努比斯', 'ジャッジメント・オブ・アヌビス', 'Effect Monster', 'Fiend', 'EARTH', 10, 3000, NULL, '这张卡不能通常召唤。自己墓地有「王家的神殿」或陷阱卡合计3种类以上存在的状态，让那之内的2种类各1张用喜欢的顺序回到卡组下面的场合才能从手卡·墓地特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：把这张卡从手卡送去墓地才能发动。从卡组把1只「带刻印者」加入手卡。 ②：自己场上的魔法·陷阱卡被效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(41098335, 'Ape Fighter', '战士猿', 'ファイターズ・エイプ', 'Effect Monster', 'Beast', 'DARK', 4, 1900, 1200, '这张卡战斗破坏对方怪兽的场合，这张卡的攻击力上升300。这张卡在自己回合没有进行攻击的场合，这个效果上升的数值在那个回合的结束阶段时回到0。'),
(31975743, 'Ape Magician', '魔法师猿', 'マジシャンズ・エイプ', 'Effect Monster', 'Beast', 'DARK', 3, 800, 1200, '这张卡不能特殊召唤。这张卡在场上表侧攻击表示存在的场合，1回合1次，把手卡1只怪兽送去墓地，选择对方场上表侧守备表示存在的1只怪兽才能发动。直到这个回合的结束阶段时，得到选择的怪兽的控制权。这个效果得到控制权的怪兽在这个回合不能把表示形式变更。'),
(44886582, 'Apex Polymerization', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(25573115, 'Apex Predation', '绝对的捕食', '絶対なる捕食', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：通常召唤的怪兽在自己场上存在的场合才能发动。场上的特殊召唤的怪兽全部破坏。这张卡的发动后，直到下次的自己回合的结束时自己不能通常召唤。'),
(41158734, 'Apocatequil', '阿普卡提基尔', 'アポカテクイル', 'Effect Monster', 'Thunder', 'LIGHT', 4, 1800, 1200, '自己场上有调整表侧表示存在的场合，场上表侧表示存在的这张卡的等级当作5星使用。场上存在的这张卡被破坏送去墓地时，可以选择自己墓地存在的1只「太阳之神官」特殊召唤。'),
(28531163, 'Apocavities', '默齿录', '黙歯録', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，对方场上的卡数量的龋齿指示物给这张卡放置。 ②：以对方场上1只表侧表示怪兽为对象，把自己场上最多4个龋齿指示物取除才能发动。取除的指示物数量的以下效果对那只怪兽适用。 ●1个：攻击力下降500。 ●2个：攻击力变成0。 ●3个：效果无效。 ●4个：破坏。'),
(4280258, 'Apollousa, Bow of the Goddess', '召命之神弓－阿波罗萨', '召命の神弓－アポロウーサ', 'Link Monster', 'Fairy', 'WIND', NULL, -1, NULL, '衍生物以外的卡名不同的怪兽2只以上 ①：「召命之神弓-阿波罗萨」在自己场上只能有1张表侧表示存在。 ②：这张卡的原本攻击力变成作为这张卡的连接素材的怪兽数量×800。 ③：对方把怪兽的效果发动时才能发动（同一连锁上最多1次）。这张卡的攻击力下降800，那个发动无效。'),
(95561146, 'Apophis the Serpent', '阿波菲斯的蛇神', 'アポピスの蛇神', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡发动后变成通常怪兽（爬虫类族·地·4星·攻1600/守1800）在怪兽区域特殊召唤（也当作陷阱卡使用）。那之后，可以从卡组把「阿匹卜之蛇神」以外的1张「阿匹卜」陷阱卡在自己场上盖放。这个效果盖放的卡在盖放的回合也能发动。 ②：这张卡被送去墓地的场合才能发动。从卡组把1张「阿匹卜之化神」加入手卡。'),
(85888377, 'Apophis the Swamp Deity', '淀神 阿波菲斯', '澱神アポピス', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段才能把这张卡发动。这张卡变成通常怪兽（爬虫类族·地·6星·攻2000/守2200）在怪兽区域特殊召唤（也当作陷阱卡使用）。那之后，自己场上有其他的永续陷阱卡存在的场合，可以让最多有那个数量的对方场上的表侧表示卡的效果直到回合结束时无效。'),
(40061558, 'Apoqliphort Skybase', '隐藏的机壳内核 无神论', 'アポクリフォート・カーネル', 'Effect Monster', 'Machine', 'EARTH', 9, 2900, 2500, '这张卡不能特殊召唤，把自己场上3只「机壳」怪兽解放的场合才能通常召唤。 ①：通常召唤的这张卡不受魔法·陷阱卡的效果影响，也不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ②：1回合1次，以对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(27279764, 'Apoqliphort Towers', '隐藏的机壳杀手 物质主义', 'アポクリフォート・キラー', 'Effect Monster', 'Machine', 'EARTH', 10, 3000, 2600, '这张卡不能特殊召唤，把自己场上3只「机壳」怪兽解放的场合才能通常召唤。 ①：通常召唤的这张卡不受魔法·陷阱卡的效果影响，也不受原本的等级或者阶级比这张卡的等级低的怪兽发动的效果影响。 ②：只要这张卡在怪兽区域存在，特殊召唤的怪兽的攻击力·守备力下降500。 ③：1回合1次，自己主要阶段才能发动。对方必须把自身的手卡·场上1只怪兽送去墓地。'),
(91392974, 'Apparition', '出幻', '出幻', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：自己场上的表侧表示的「英雄」怪兽被战斗·效果破坏的场合才能发动。从卡组把1只4星以下的「幻影英雄」怪兽特殊召唤。那之后，可以选对方场上1只怪兽，那个原本的攻击力·守备力变成一半。'),
(56132807, 'Apple Magician Girl', '苹果魔术少女', 'アップル・マジシャン・ガール', 'Effect Monster', 'Spellcaster', 'FIRE', 3, 1200, 800, '①：1回合1次，这张卡被选择作为攻击对象的场合才能发动。从手卡把1只5星以下的魔法师族怪兽特殊召唤。那之后，攻击对象转移为那只怪兽，攻击怪兽的攻击力变成一半。 ②：这张卡被战斗·效果破坏的场合，以这张卡以外的自己墓地最多3只「魔术少女」怪兽为对象才能发动（同名卡最多1张）。那些卡加入手卡。'),
(43341600, 'Apple of Enlightenment', '福瑞雅的苹果', 'フライアのリンゴ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：以最多有自己场上的「女武神」怪兽数量的对方墓地的卡为对象才能发动。那些卡除外。 ②：盖放的这张卡因对方的效果从场上离开，被送去墓地的场合或者被除外的场合才能发动。自己从卡组抽出自己场上的「女武神」怪兽的数量＋1张。'),
(5846183, 'Appliancer Breakerbuncle', '遮断机块 断路红玉兽', '遮断機塊ブレイカーバンクル', 'Effect Monster', 'Machine', 'WATER', 1, NULL, NULL, '①：自己的「机块」怪兽和对方怪兽进行战斗的伤害计算时，把这张卡从手卡丢弃才能发动。那只自己怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害变成0。 ②：自己场上的「机块」怪兽被效果破坏的场合，可以作为代替把场上·墓地的这张卡除外。'),
(78225596, 'Appliancer Celtopus', '充电机块 电池章鱼', '充電機塊セルトパス', 'Link Monster', 'Machine', 'DARK', NULL, NULL, NULL, '「机块」怪兽2只 ①：连接状态的这张卡不会成为攻击对象，也不会成为对方的效果的对象。 ②：这张卡所互相连接区的自己的「机块」连接怪兽在和对方怪兽进行战斗的伤害计算时发动。那只自己怪兽的攻击力只在那次伤害计算时上升这张卡所互相连接区的怪兽数量×1000。 ③：1回合1次，和这张卡没有互相连接的自己场上的「机块」连接怪兽被战斗·效果破坏的场合才能发动。自己从卡组抽1张。'),
(27157996, 'Appliancer Conversion', '机块变换', '機塊コンバート', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的主要怪兽区域的「机块」连接怪兽全部除外。那之后，可以选最多有这个效果除外的怪兽数量的除外中的自己的「机块」连接怪兽特殊召唤。 ②：这张卡在墓地存在的场合，自己主要阶段从自己墓地把1张其他的「机块」魔法·陷阱卡除外才能发动。这张卡加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(41830887, 'Appliancer Copybokkle', '复写机块 复印小矮人', '複写機塊コピーボックル', 'Effect Monster', 'Machine', 'DARK', 1, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：以自己场上1只「机块」怪兽为对象才能发动。这张卡从手卡特殊召唤。这个效果特殊召唤的这张卡直到结束阶段当作和作为对象的怪兽同名卡使用。 ②：把墓地的这张卡除外，以自己场上1只「机块」怪兽为对象才能发动。从自己的手卡·墓地选1只那只怪兽的同名怪兽特殊召唤。这个效果在这张卡送去墓地的回合不能发动。'),
(3507053, 'Appliancer Dryer Drake', '干燥机块 烘干龙兽', '乾燥機塊ドライドレイク', 'Link Monster', 'Machine', 'FIRE', NULL, NULL, NULL, '「机块」怪兽1只 这张卡在连接召唤的回合不能作为连接素材。 ①：连接状态的这张卡的攻击力上升1000。 ②：自己战斗阶段1次，这张卡是互相连接状态的场合才能发动。选包含这张卡的自己的主要怪兽区域2只「机块」怪兽，那些位置交换。这个回合，那另1只怪兽在同1次的战斗阶段中可以作2次攻击。 ③：1回合1次，不在互相连接状态的这张卡成为攻击对象时才能发动。那次攻击无效。'),
(3875465, 'Appliancer Electrilyrical World', '家电机块世界', '家電機塊世界エレクトリリカル・ワールド', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把场地魔法卡以外的1张「机块」卡加入手卡。 ②：1回合1次，自己对「机块」连接怪兽的连接召唤成功的场合才能发动。从自己墓地选1只「机块」怪兽加入手卡。 ③：1回合1次，自己或者对方的怪兽的攻击宣言时才能发动。选自己场上1只「机块」怪兽，那个位置向其他的自己的主要怪兽区域移动。'),
(4729591, 'Appliancer Kappa Scale', '计量机块 电子秤河童', '計量機塊カッパスケール', 'Link Monster', 'Machine', 'WATER', NULL, NULL, NULL, '「机块」怪兽1只 这个卡名的①②的效果1回合各能使用1次。这张卡在连接召唤的回合不能作为连接素材。 ①：把互相连接状态的这张卡解放才能发动。从自己墓地选「计量机块 电子秤河童」以外的1只「机块」连接怪兽特殊召唤。 ②：把不在互相连接状态的这张卡解放才能发动。从自己墓地选1只4星以下的「机块」怪兽特殊召唤。'),
(77102944, 'Appliancer Laundry Dragon', '洗濯机块 洗衣龙', '洗濯機塊ランドリードラゴン', 'Link Monster', 'Machine', 'WATER', NULL, 1500, NULL, '「机块」怪兽1只 这张卡在连接召唤的回合不能作为连接素材。 ①：这张卡的战斗发生的双方的战斗伤害变成0。 ②：1回合1次，互相连接状态的这张卡在和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽除外。 ③：1回合1次，不在互相连接状态的这张卡在和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(81769387, 'Appliancer Propelion', '扇风机块 螺旋风扇狮', '扇風機塊プロペライオン', 'Link Monster', 'Machine', 'WIND', NULL, 1200, NULL, '「机块」怪兽1只 这张卡在连接召唤的回合不能作为连接素材。 ①：这张卡可以直接攻击。 ②：1回合1次，这张卡是互相连接状态的场合，自己和对方的怪兽之间进行战斗的伤害计算时才能发动。那只对方怪兽的攻击力只在那次伤害计算时变成0。 ③：1回合1次，不在互相连接状态的这张卡在和对方怪兽进行战斗的伤害计算时才能发动。那只对方怪兽的攻击力只在那次伤害计算时变成0。'),
(30996652, 'Appliancer Reuse', '机块再利用', '機塊リユース', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地1只「机块」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽从场上离开的场合回到持有者卡组最下面。'),
(78447174, 'Appliancer Socketroll', '电幻机块 插座小人', '電幻機塊コンセントロール', 'Effect Monster', 'Machine', 'DARK', 1, 100, 100, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「机块」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡已在怪兽区域存在的状态，自己场上有其他的「电幻机块 插座小人」特殊召唤的场合才能发动。从卡组把1只「电幻机块 插座小人」特殊召唤。'),
(66380357, 'Appliancer Test', '机块测试', '機塊テスト', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己场上1只「机块」连接怪兽为对象才能发动。从自己墓地把连接1「机块」连接怪兽尽可能在作为那只怪兽所连接区的自己场上特殊召唤。这个效果特殊召唤的怪兽在结束阶段除外。'),
(30118200, 'Appliancer Vacculephant', '扫除机块 真空吸尘象', '掃除機塊バキューネシア', 'Link Monster', 'Machine', 'DARK', NULL, 1000, NULL, '「机块」怪兽1只 这个卡名的①②的效果1回合只能有1次使用其中任意1个。这张卡在连接召唤的回合不能作为连接素材。 ①：把1张手卡送去墓地，以对方场上1张卡为对象才能发动。那张卡破坏。 ②：这张卡是互相连接状态的场合，以对方的主要怪兽区域1只怪兽为对象才能发动。那只怪兽破坏。 ③：这张卡不是互相连接状态的场合，这张卡可以直接攻击。'),
(43262273, 'Appointer of the Red Lotus', '红莲指名者', '紅蓮の指名者', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：支付2000基本分，把手卡全部给对方观看才能发动。把对方手卡确认，从那之中选1张直到下次的对方结束阶段除外。'),
(30603688, 'Apprentice Illusion Magician', '幻想见习魔导师', '幻想の見習い魔導師', 'Effect Monster', 'Spellcaster', 'DARK', 6, 2000, 1700, '①：这张卡可以丢弃1张手卡，从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把1只「黑魔术师」加入手卡。 ③：自己·对方回合，其他的自己的魔法师族·暗属性怪兽和对方怪兽进行战斗的伤害计算时，把手卡·场上的这张卡送去墓地才能发动。那只自己怪兽的攻击力·守备力只在那次伤害计算时上升2000。'),
(9156135, 'Apprentice Magician', '见习魔术师', '見習い魔術師', 'Effect Monster', 'Spellcaster', 'DARK', 2, 400, 800, '①：这张卡召唤·反转召唤·特殊召唤成功的场合，以场上1张可以放置魔力指示物的卡为对象发动。给那张卡放置1个魔力指示物。 ②：这张卡被战斗破坏时才能发动。从卡组把1只2星以下的魔法师族怪兽里侧守备表示特殊召唤。'),
(64977888, 'Apprentice Piper', '见习魔笛使', '見習い魔笛使い', 'Flip Effect Monster', 'Spellcaster', 'DARK', 2, 100, 1500, '①：这张卡反转的场合才能发动。从手卡把1只怪兽特殊召唤。 ②：这张卡被战斗·效果破坏送去墓地的场合才能发动。从手卡把1只怪兽特殊召唤。'),
(48539234, 'Appropriate', '便乘', '便乗', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '对方在抽卡阶段以外抽卡时才能发动。那之后，每次对方在抽卡阶段以外抽卡，从自己卡组抽2张卡。'),
(96427353, 'Aqua Armor Ninja', '机甲忍者 水', '機甲忍者アクア', 'Effect Monster', 'Warrior', 'WATER', 4, 800, 1600, '对方怪兽的直接攻击宣言时，自己墓地有这张卡以外的名字带有「忍者」的怪兽存在的场合，把墓地的这张卡从游戏中除外才能发动。把1只攻击怪兽的攻击无效。'),
(95132338, 'Aqua Chorus', '水之合唱', 'アクアの合唱', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：场上有同名怪兽存在的场上的怪兽的攻击力·守备力上升500。'),
(59131526, 'Aqua Chorus Round', '水之轮唱', 'アクアの輪唱', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己1张手卡除外。下次的自己准备阶段，可以把最多2张这个效果除外的卡的同名卡从卡组加入手卡。对方场上没有卡存在的状态把这张卡发动过的场合，直到发动的回合的结束时自己不能把这个效果除外的卡以及原本卡名和那张卡相同的卡的效果发动。'),
(86164529, 'Aqua Dragon', '水精龙', 'アクア・ドラゴン', 'Fusion Monster', 'Sea Serpent', 'WATER', 6, 2250, 1900, '「妖精龙」＋「海原的女战士」＋「区域吞噬者」'),
(7653207, 'Aqua Jet', '喷水引擎', 'アクア・ジェット', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己场上1只鱼族·海龙族·水族怪兽为对象才能发动。那只怪兽的攻击力上升1000。'),
(32278723, 'Aqua Jet Surface', '水波喷气机・上浮', 'アクア・ジェット・サーフェス', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·墓地把1只4星以下的鱼族·海龙族·水族怪兽特殊召唤。只要这个效果特殊召唤的怪兽在自己场上表侧表示存在，自己不是超量怪兽不能从额外卡组特殊召唤。 ②：对方场上有攻击表示怪兽存在的场合，把墓地的这张卡除外，以自己场上1只鱼族·海龙族·水族怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时上升1000。'),
(85639257, 'Aqua Madoor', '水魔道士', 'アクア・マドール', 'Normal Monster', 'Spellcaster', 'WATER', 4, 1200, 2000, '操纵水的魔法师。造出厚重的水墙压垮敌人。'),
(12436646, 'Aqua Snake', '水蛇', 'アクア・スネーク', 'Normal Monster', 'Aqua', 'WATER', 3, 1050, 900, '尾巴前端的光球可施展催眠术，使对方精神恍惚。'),
(40916023, 'Aqua Spirit', '水之精灵 阿库艾丽娅', '水の精霊 アクエリア', 'Effect Monster', 'Aqua', 'WATER', 4, 1600, 1200, '这张卡不能通常召唤。从自己墓地把1只水属性怪兽除外的场合可以特殊召唤。 ①：对方准备阶段，以对方场上1只表侧表示怪兽为对象才能发动。那只对方的表侧表示怪兽的表示形式变更。这个回合，那只怪兽不能把表示形式变更。'),
(28325165, 'Aqua Story - Urashima', '水物语-浦岛', '水物語－ウラシマ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己墓地有「水伶女」怪兽存在的场合，以场上1只怪兽为对象才能发动。直到回合结束时，那只怪兽的效果无效化，攻击力·守备力变成100，不受对方的效果影响。'),
(92053608, 'Aquaactress Arowana', '水伶女·龙鱼', 'アクアアクトレス・アロワナ', 'Effect Monster', 'Aqua', 'WATER', 6, 2000, 2000, '①：1回合1次，自己主要阶段才能发动。从卡组把1只「水伶女」怪兽加入手卡。'),
(66668900, 'Aquaactress Guppy', '水伶女·孔雀鱼', 'アクアアクトレス・グッピー', 'Effect Monster', 'Aqua', 'WATER', 2, 600, 600, '①：1回合1次，自己主要阶段才能发动。从手卡把1只「水伶女」怪兽特殊召唤。'),
(39260991, 'Aquaactress Tetra', '水伶女·灯鱼', 'アクアアクトレス・テトラ', 'Effect Monster', 'Aqua', 'WATER', 1, 300, 300, '①：1回合1次，自己主要阶段才能发动。从卡组把1张「水族馆」卡加入手卡。'),
(78910579, 'Aquamirror Cycle', '仪水镜之反魂术', '儀水鏡の反魂術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上1只水属性怪兽回到卡组，选择自己墓地存在的2只水属性怪兽加入手卡。'),
(64437633, 'Aquamirror Illusion', '仪水镜之幻象术', '儀水鏡の幻影術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '从手卡把1只名字带有「遗式」的仪式怪兽特殊召唤。这个效果特殊召唤的仪式怪兽不能攻击，结束阶段时回到持有者手卡。'),
(46337945, 'Aquamirror Meditation', '仪水镜之冥想术', '儀水鏡の瞑想術', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把手卡1张仪式魔法卡给对方观看，选择自己墓地存在的2只名字带有「遗式」的怪兽发动。选择的墓地的怪兽回到手卡。'),
(22377815, 'Aquarian Alessa', '水面之艾瑞莎', '水面のアレサ', 'Gemini Monster', 'Aqua', 'WATER', 4, 1500, 500, '这张卡在墓地或者场上表侧表示存在的场合，当作通常怪兽使用。场上表侧表示存在的这张卡可以作当通常召唤使用的再度召唤，这张卡当作效果怪兽使用并得到以下效果。 ●这张卡战斗破坏对方怪兽送去墓地时，对方手卡随机丢弃1张。'),
(91831066, 'Aquarium Lighting', '水照明', '水照明', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：「水照明」在自己场上只能有1张表侧表示存在。 ②：自己的「水伶女」怪兽和对方怪兽进行战斗的伤害计算时发动。那只自己怪兽的攻击力·守备力只在伤害计算时变成2倍。 ③：这张卡从场上送去墓地的场合，以自己墓地1只水族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是水族怪兽不能特殊召唤。'),
(65446452, 'Aquarium Set', '水舞台装置', '水舞台装置', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的水属性怪兽的攻击力·守备力上升300。 ②：自己场上的「水伶女」怪兽的攻击力·守备力上升300。 ③：这张卡从场上送去墓地的场合，以自己墓地1只水族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是水族怪兽不能特殊召唤。'),
(29047353, 'Aquarium Stage', '水舞台', '水舞台', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己场上的水属性怪兽不会被和水属性以外的怪兽的战斗破坏。 ②：自己场上的「水伶女」怪兽不受对方怪兽的效果影响。 ③：这张卡从场上送去墓地的场合，以自己墓地1只水族怪兽为对象才能发动。那只怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不是水族怪兽不能特殊召唤。'),
(75771170, 'Arahime the Manifested Mikanko', '荒日女之御巫', 'アラヒメの御巫', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 9, NULL, NULL, '「御巫神乐」降临 这个卡名的①的效果1回合只能使用1次。 ①：这张卡在手卡·墓地存在，自己墓地有其他的「御巫」卡存在的场合，以场上1只表侧表示怪兽为对象才能发动。这张卡当作装备魔法卡使用给那只怪兽装备。 ②：这张卡装备中的场合，自己·对方的结束阶段才能发动。这张卡和装备怪兽回到手卡。 ③：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。'),
(16889337, 'Aratama', '荒魂', '荒魂', 'Spirit Monster', 'Fiend', 'DARK', 4, 800, 1800, '这张卡不能特殊召唤。 ①：这张卡召唤·反转时才能发动。从卡组把「荒魂」以外的1只灵魂怪兽加入手卡。 ②：这张卡召唤·反转的回合的结束阶段发动。这张卡回到手卡。'),
(57964143, 'Arbitration of White', '白之仲裁', '白の仲裁', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②③的效果1回合各能使用1次。 ①：以自己场上1只鱼族怪兽为对象才能发动。这个回合，那只怪兽当作调整使用。 ②：对方怪兽的攻击宣言时，从手卡丢弃1只鱼族怪兽才能发动。对方场上的怪兽全部变成守备表示。 ③：自己的鱼族怪兽被战斗破坏的场合或者被送去墓地的场合，把魔法与陷阱区域的表侧表示的这张卡送去墓地才能发动。从自己墓地把1只鱼族怪兽特殊召唤。'),
(64276752, 'Arc Rebellion Xyz Dragon', '弧反叛超量龙', 'アーク・リベリオン・エクシーズ・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 5, 3000, 2500, '5星怪兽×3 这个卡名的②的效果1回合只能使用1次。 ①：超量召唤的这张卡不会被效果破坏。 ②：把这张卡1个超量素材取除才能发动。这张卡的攻击力上升这张卡以外的场上的怪兽的原本攻击力的合计数值。这张卡有暗属性超量怪兽在作为超量素材的场合，再让这张卡以外的场上的全部表侧表示怪兽的效果无效化。这个效果的发动后，直到回合结束时自己不用这张卡不能攻击宣言。'),
(99189322, 'Arcana Call', '秘仪呼唤', 'アルカナコール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「秘仪之力」的怪兽发动。把墓地存在的1只名字带有「秘仪之力」的怪兽从游戏中除外。直到结束阶段时，选择怪兽的投掷硬币所得效果变成从游戏中除外的怪兽的投掷硬币所得效果相同的效果。'),
(64454614, 'Arcana Extra Joker', '天位准骑士', 'アルカナ エクストラジョーカー', 'Link Monster', 'Warrior', 'LIGHT', NULL, 2800, NULL, '卡名不同的战士族怪兽3只 ①：1回合1次，以场上的这张卡或者这张卡所连接区的怪兽为对象的怪兽的效果·魔法·陷阱卡发动时，把和那张卡相同种类（怪兽·魔法·陷阱）的1张手卡丢弃才能发动。那个发动无效。 ②：连接召唤的这张卡被战斗破坏送去墓地时才能发动。从卡组把1只战士族·4星的通常怪兽特殊召唤，从卡组把1只战士族·4星怪兽加入手卡。'),
(62892347, 'Arcana Force 0 - The Fool', '秘仪之力０－愚者', 'アルカナフォース０－THE FOOL', 'Effect Monster', 'Fairy', 'LIGHT', 1, NULL, NULL, '这张卡不会被战斗破坏。这张卡不能变成守备表示。这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：这张卡为对象的自己的魔法·陷阱·效果怪兽的效果无效并破坏。 ●里：这张卡为对象的对方的魔法·陷阱·效果怪兽的效果无效并破坏。'),
(12686296, 'Arcana Force EX - The Chaos Ruler', '秘仪之力EX－混沌统御者', 'アルカナフォースEX－THE CHAOS RULER', 'Fusion Monster', 'Fairy', 'LIGHT', 10, 3300, 3300, '卡名不同的「秘仪之力」怪兽×3 把自己·对方场上的上记的卡送去墓地的场合才能特殊召唤。 ①：这张卡特殊召唤的场合发动。进行1次投掷硬币，那个里表的以下效果适用。 ●表：把1只10星「秘仪之力」怪兽无视召唤条件从手卡·卡组特殊召唤。 ●里：把持有进行投掷硬币效果的1张卡从卡组加入手卡。 ②：只要「光之结界」在场地区域存在，对方不能把场上的怪兽的效果发动。'),
(69831560, 'Arcana Force EX - The Dark Ruler', '秘仪之力EX－暗之统御者', 'アルカナフォースEX－THE DARK RULER', 'Effect Monster', 'Fairy', 'LIGHT', 10, 4000, 4000, '这张卡不能通常召唤。把自己场上存在的3只怪兽送去墓地的场合才能特殊召唤。这张卡特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：这张卡在战斗阶段中可以作2次攻击。进行这个效果适用的第2次战斗的场合，这张卡在战斗阶段结束时变成守备表示。直到下次的自己回合结束时这张卡不能把表示形式改变。 ●里：这张卡被破坏的场合，场上的卡全部破坏。'),
(5861892, 'Arcana Force EX - The Light Ruler', '秘仪之力EX－光之统御者', 'アルカナフォースEX－THE LIGHT RULER', 'Effect Monster', 'Fairy', 'LIGHT', 10, 4000, 4000, '这张卡不能通常召唤。把自己场上存在的3只怪兽送去墓地的场合才能特殊召唤。这张卡特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：战斗破坏对方怪兽送去墓地时，可以从自己墓地把1张卡加入手卡。 ●里：这张卡为对象的效果怪兽的效果·魔法·陷阱卡的发动无效并破坏。每次这个效果把卡的发动无效，这张卡的攻击力下降1000。'),
(8396952, 'Arcana Force I - The Magician', '秘仪之力Ⅰ－魔术师', 'アルカナフォースⅠ－THE MAGICIAN', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1100, 1100, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：魔法卡发动时，直到那个回合的结束阶段时这张卡的原本攻击力变成2倍。 ●里：每次魔法卡发动对方回复500基本分。'),
(35781051, 'Arcana Force III - The Empress', '秘仪之力Ⅲ－女皇', 'アルカナフォースⅢ－THE EMPRESS', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1300, 1300, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：每次对方对怪兽的通常召唤成功可以从手卡把1只名字带有「秘仪之力」的怪兽在自己场上特殊召唤。 ●里：每次对方对怪兽的通常召唤成功自己把手卡1张卡送去墓地。'),
(61175706, 'Arcana Force IV - The Emperor', '秘仪之力Ⅳ－皇帝', 'アルカナフォースⅣ－THE EMPEROR', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 1400, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：自己场上表侧表示存在的名字带有「秘仪之力」的怪兽的攻击力上升500。 ●里：自己场上表侧表示存在的名字带有「秘仪之力」的怪兽的攻击力下降500。'),
(3376703, 'Arcana Force V - The Hierophant', '秘仪之力Ⅴ－教皇', 'アルカナフォースⅤ－THE HIEROPHANT', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1500, 1500, '①：把这张卡从手卡丢弃才能发动。这个回合，在自己场上有「秘仪之力」怪兽召唤·反转召唤·特殊召唤时对方不能把效果发动。 ②：这张卡召唤·反转召唤·特殊召唤的场合发动。进行1次投掷硬币，那个里表的以下效果适用。 ●表：同名怪兽不在自己的场上·墓地存在的1只4星以下的「秘仪之力」怪兽从卡组特殊召唤。 ●里：从卡组把1只「秘仪之力」怪兽在对方场上特殊召唤。'),
(97574404, 'Arcana Force VI - The Lovers', '秘仪之力Ⅵ－恋人', 'アルカナフォースⅥ－THE LOVERS', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1600, 1600, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：名字带有「秘仪之力」的怪兽祭品召唤的场合，这1只怪兽可以作为2只的数量的祭品。 ●里：名字带有「秘仪之力」的怪兽不能祭品召唤。'),
(34568403, 'Arcana Force VII - The Chariot', '秘仪之力Ⅶ－战车', 'アルカナフォースⅦ－THE CHARIOT', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1700, 1700, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：这张卡战斗破坏对方怪兽的场合，可以把那只怪兽在自己场上特殊召唤。 ●里：这张卡的控制权转移给对方。'),
(60953118, 'Arcana Force XIV - Temperance', '秘仪之力ⅩⅣ－节制', 'アルカナフォースⅩⅣ－TEMPERANCE', 'Effect Monster', 'Fairy', 'LIGHT', 6, 2400, 2400, '可以从手卡把这张卡丢弃，自己受到的战斗伤害只有1次变成0。这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：自己受到的战斗伤害变成一半数值。 ●里：对方受到的战斗伤害变成一半数值。'),
(39761418, 'Arcana Force XIX - The Sun', '秘仪之力ⅩⅨ－太阳', 'アルカナフォースⅩⅨ－THE SUN', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2900, 2900, '这个卡名的①的效果1回合只能使用1次。 ①：持有进行投掷硬币效果的卡在场上存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·反转召唤·特殊召唤的场合发动。进行1次投掷硬币，那个里表的以下效果适用。 ●表：把持有进行投掷硬币效果的1张魔法卡从卡组到自己场上盖放。 ●里：双方的魔法与陷阱区域的卡全部破坏。'),
(59712426, 'Arcana Force XV - The Fiend', '秘仪之力ⅩⅤ－魔鬼', 'アルカナフォースⅩⅤ－THE DEVIL', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2500, 2500, '①：把这张卡从手卡丢弃才能发动。从自己的卡组·墓地把1张「光之结界」加入手卡。 ②：这张卡召唤·反转召唤·特殊召唤的场合发动。进行1次投掷硬币，那个里表让这张卡得到以下效果。 ●表：这张卡进行战斗的攻击宣言时，以场上1只怪兽为对象才能发动。那只怪兽破坏，给与那个控制者500伤害。 ●里：这张卡进行战斗的攻击宣言时发动。场上的怪兽全部破坏。'),
(97452817, 'Arcana Force XVIII - The Moon', '秘仪之力ⅩⅧ－月亮', 'アルカナフォースⅩⅧ－THE MOON', 'Effect Monster', 'Fairy', 'LIGHT', 7, 2800, 2800, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：自己的准备阶段时可以在自己场上把1只「月衍生物」（天使族·光·1星·攻/守0）特殊召唤。 ●里：自己的结束阶段时只有1次，选择自己场上1只怪兽，那只怪兽的控制权转移给对方。'),
(23846921, 'Arcana Force XXI - The World', '秘仪之力ⅩⅩⅠ－世界', 'アルカナフォースⅩⅩⅠ－THE WORLD', 'Effect Monster', 'Fairy', 'LIGHT', 8, 3100, 3100, '这张卡召唤·反转召唤·特殊召唤成功时，进行1次投掷硬币得到以下效果。 ●表：自己的结束阶段时可以把自己场上存在的2只怪兽送去墓地让下次的对方回合跳过。 ●里：对方的抽卡阶段时把对方墓地最上面1张卡加入对方手卡。'),
(6150044, 'Arcana Knight Joker', '天位骑士', 'アルカナ ナイトジョーカー', 'Fusion Monster', 'Warrior', 'LIGHT', 9, 3800, 2500, '「王后骑士」＋「卫兵骑士」＋「国王骑士」 这张卡的融合召唤不用上记的卡不能进行。 ①：1回合1次，场上的这张卡为对象的怪兽的效果·魔法·陷阱卡发动时，把和那张卡相同种类（怪兽·魔法·陷阱）的1张手卡丢弃才能发动。那个效果无效。'),
(11819473, 'Arcana Reading', '秘仪读牌', 'アルカナリーディング', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：进行1次投掷硬币，那个里表的以下效果适用。自己的场地区域有「光之结界」存在的场合，不进行投掷硬币而选里表的其中1个适用。 ●表：从卡组把「秘仪读牌」以外的1张持有进行投掷硬币效果的卡加入手卡。 ●里：对方从自身卡组选1张卡加入手卡。 ②：把墓地的这张卡除外才能发动。从手卡把1只「秘仪之力」怪兽召唤。'),
(76302448, 'Arcana Spread', '秘仪牌阵', 'アルカナスプレッド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：进行1次投掷硬币，那个里表的以下效果适用。自己的场地区域有「光之结界」存在的场合，不进行投掷硬币而选里表的其中1个适用。 ●表：从卡组把1只4星以下的「秘仪之力」怪兽特殊召唤。 ●里：把持有进行投掷硬币效果的1只怪兽从自己墓地特殊召唤。 ②：把墓地的这张卡除外才能发动。把持有进行投掷硬币效果的1张卡从自己墓地加入手卡。'),
(93880808, 'Arcana Triumph Joker', '天位金骑士', 'アルカナ トライアンフジョーカー', 'Effect Monster', 'Warrior', 'LIGHT', 10, -1, 2500, '①：这张卡在手卡·墓地存在的场合，从手卡以及自己场上的表侧表示怪兽之中把「王后骑士」「卫兵骑士」「国王骑士」各1只送去墓地才能发动。这张卡特殊召唤。 ②：这张卡的攻击力上升双方手卡数量×500。 ③：丢弃1张手卡才能发动。和丢弃的卡相同种类（怪兽·魔法·陷阱）的对方场上的表侧表示的卡全部破坏。'),
(40048324, 'Arcane Apprentice', '密术炼贤', 'アーケイン・ファイロ', 'Tuner Monster', 'Spellcaster', 'FIRE', 2, 1000, 400, '这张卡被同调怪兽的同调召唤使用送去墓地的场合，可以从自己卡组把1张「爆裂模式」加入手卡。'),
(55001420, 'Arcane Archer of the Forest', '深绿之魔弓使', '深緑の魔弓使い', 'Effect Monster', 'Warrior', 'EARTH', 3, 900, 1400, '若自己场上有植物族怪兽存在，则这张卡不能被攻击。每祭掉自己场上1只植物族怪兽，就能破坏场上1张魔法·陷阱卡。'),
(17896384, 'Arcane Barrier', '魔法族的结界', '魔法族の結界', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：每次场上的表侧表示的魔法师族怪兽被破坏给这张卡放置1个魔力指示物（最多4个）。 ②：把有魔力指示物放置的这张卡和自己场上1只表侧表示的魔法师族怪兽送去墓地才能发动。自己从卡组抽出这张卡放置的魔力指示物的数量。'),
(31924889, 'Arcanite Magician', '奥法魔术士', 'アーカナイト・マジシャン', 'Synchro Monster', 'Spellcaster', 'LIGHT', 7, 400, 1800, '调整＋调整以外的魔法师族怪兽1只以上 ①：这张卡同调召唤成功的场合发动。给这张卡放置2个魔力指示物。 ②：这张卡的攻击力上升这张卡的魔力指示物数量×1000。 ③：把自己场上1个魔力指示物取除，以对方场上1张卡为对象才能发动。那张对方的卡破坏。'),
(14553285, 'Arcanite Magician/Assault Mode', '奥法魔术士／爆裂', 'アーカナイト・マジシャン／バスター', 'Effect Monster', 'Spellcaster', 'LIGHT', 9, 900, 2300, '这张卡不能通常召唤。「爆裂模式」的效果才能特殊召唤。这张卡特殊召唤成功时，给这张卡放置2个魔力指示物。这张卡放置的魔力指示物每有1个，这张卡的攻击力上升1000。可以把这张卡放置的2个魔力指示物取除，对方场上存在的卡全部破坏。此外，场上存在的这张卡被破坏时，可以把自己墓地存在的1只「奥金魔导师」特殊召唤。'),
(45349196, 'Archfiend Black Skull Dragon', '凶魔龙 黑恶魔龙', '悪魔竜ブラック・デーモンズ・ドラゴン', 'Fusion Monster', 'Dragon', 'DARK', 9, 3200, 2500, '6星「恶魔」通常怪兽＋「真红眼」通常怪兽 自己对「恶魔龙 暗黑魔龙」1回合只能有1次特殊召唤。 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：融合召唤的这张卡进行战斗的战斗阶段结束时，以自己墓地1只「真红眼」通常怪兽为对象才能发动。给与对方为墓地的那只怪兽的原本攻击力数值的伤害。那之后，那只怪兽回到卡组。'),
(92039899, 'Archfiend Cavalry', '恶魔的骑兵', 'デーモンの騎兵', 'Effect Monster', 'Fiend', 'DARK', 4, 1900, NULL, '①：场上的这张卡被效果破坏送去墓地的场合，以「恶魔骑兵」以外的自己墓地1只「恶魔」怪兽为对象才能发动。那只怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(68371799, 'Archfiend Commander', '恶魔的将星', 'デーモンの将星', 'Effect Monster', 'Fiend', 'DARK', 6, 2500, 1200, '这个卡名的①的方法的特殊召唤1回合只能有1次。 ①：自己场上有「恶魔」卡存在的场合，这张卡可以从手卡特殊召唤。这个回合，这张卡不能攻击。 ②：这张卡的①的方法特殊召唤成功的场合，以自己场上1张「恶魔」卡为对象发动。那张自己的「恶魔」卡破坏。 ③：这张卡上级召唤成功时，以自己墓地1只6星「恶魔」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。'),
(57624336, 'Archfiend Eccentrick', '古怪诡计恶魔', 'エキセントリック・デーモン', 'Pendulum Effect Monster', 'Fiend', 'LIGHT', 3, 800, 1000, '这个卡名的怪兽效果1回合只能使用1次。 ①：把这张卡解放，以场上1只怪兽为对象才能发动。那只怪兽破坏。'),
(48469380, 'Archfiend Emperor', '死亡皇帝恶魔', 'デス・エンペラー・デーモン', 'Pendulum Effect Ritual Monster', 'Fiend', 'FIRE', 7, 2500, 1200, '「恶魔们的玉座」降临 这张卡不用仪式召唤不能特殊召唤。这个卡名的①③的怪兽效果1回合各能使用1次。 ①：这张卡从额外卡组仪式召唤的场合才能发动。额外怪兽区域以外的场上的怪兽全部除外。 ②：额外怪兽区域的这张卡不受其他怪兽的效果影响。 ③：这张卡在额外怪兽区域存在的场合才能发动。自己的手卡·卡组·墓地·除外状态的1只恶魔族怪兽特殊召唤。');